// Portable SDK v1 plugin. No imports from the application or Node APIs.
const baselines = {
  "2.1.322": {
    "user-agent": "claude-cli/2.1.322 (external, sdk-cli)",
    "x-app": "cli",
    "anthropic-version": "2023-06-01",
    "anthropic-dangerous-direct-browser-access": "true",
    "anthropic-beta":
      "claude-code-20250219,interleaved-thinking-2025-05-14,context-management-2025-06-27,thinking-token-count-2026-05-13,advanced-tool-use-2025-11-20,effort-2025-11-24,thinking-display-updates-2026-08-18",
    "x-stainless-lang": "js",
    "x-stainless-package-version": "0.128.0",
    "x-stainless-runtime": "node",
    "x-stainless-runtime-version": "v26.12.1",
    "x-stainless-arch": "x64",
    "x-stainless-os": "Windows",
    "x-stainless-retry-count": "0",
    "x-stainless-timeout": "600",
  },
};

function object(raw, label) {
  const value = JSON.parse(raw || "{}");
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error(`${label} must be a JSON object`);
  if (
    Object.keys(value).some((key) =>
      ["__proto__", "prototype", "constructor"].includes(key),
    )
  )
    throw new Error(`Invalid ${label} key`);
  return value;
}

export function prepareChat(chat, context) {
  const { config, endpoint, sessionId, requestId } = context;
  if (config.mode !== "cli") return null;
  if (!config.bridgeToken)
    throw new Error("请配置桥接服务令牌 / Configure the bridge token");
  if (!/^\d+\.\d+\.\d+$/.test(config.cliVersion))
    throw new Error("Specify an exact Claude Code version");
  return {
    url: `${config.bridgeUrl.replace(/\/+$/, "")}/v1/drivers/claude-code/chat`,
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${config.bridgeToken}`,
    },
    body: {
      ...chat,
      endpoint: { baseUrl: endpoint.baseUrl, apiKey: endpoint.apiKey },
      sessionId,
      requestId,
      cliVersion: config.cliVersion,
      authType: config.authType,
      betas: config.beta
        ? config.beta
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean)
        : [],
    },
  };
}

export function prepareRequest(request, context) {
  const { config, endpoint, operation, sessionId } = context;
  if (config.mode === "cli") {
    if (operation === "models")
      throw new Error(
        "真实 CLI 模式请手动添加模型，避免向 CLI 专用网关发送标准模型列表请求。 / Add models manually in real CLI mode.",
      );
    throw new Error("Real CLI requests must use the client driver");
  }
  const baseline = baselines[config.cliVersion];
  if (!baseline)
    throw new Error(
      `No verified HTTP preset for Claude Code ${config.cliVersion}; use real CLI mode or install a newer plugin.`,
    );
  const headers = {
    ...request.headers,
    ...baseline,
    "x-claude-code-session-id": sessionId,
  };
  if (config.userAgent) headers["user-agent"] = config.userAgent;
  if (config.beta) headers["anthropic-beta"] = config.beta;
  if (config.authType === "bearer") {
    delete headers["x-api-key"];
    headers.authorization = `Bearer ${endpoint.apiKey}`;
  }
  for (const [name, value] of Object.entries(
    object(config.headerOverrides, "headers"),
  )) {
    if (typeof value !== "string")
      throw new Error("Header values must be strings");
    const normalized = name.toLowerCase();
    if (
      ["host", "content-length", "connection", "transfer-encoding"].includes(
        normalized,
      )
    )
      throw new Error(`Transport header cannot be overridden: ${name}`);
    headers[normalized] = value;
  }
  if (operation === "models") return { ...request, headers };
  const url = new URL(request.url);
  url.searchParams.set("beta", "true");
  const body = { ...request.body, ...object(config.bodyOverrides, "body") };
  // Never invent CLI tools, billing hashes or thinking signatures. The default
  // simulation preserves the application's system prompt and real tools.
  return { url: url.toString(), headers, body };
}
